"""Vault API request/response types."""

from __future__ import annotations

from enum import StrEnum

from pydantic import BaseModel, ConfigDict, Field


class VaultProvider(StrEnum):
    """Supported vault providers."""

    ONE_PASSWORD = "1password"
    BITWARDEN = "bitwarden"


class VaultFieldType(StrEnum):
    """Vault item field data type."""

    STRING = "STRING"
    CONCEALED = "CONCEALED"
    OTP = "OTP"


class FieldMetadata(BaseModel):
    """Metadata for a single field within a vault item."""

    model_config = ConfigDict(populate_by_name=True)

    field_id: str = Field(..., alias="fieldId", description="Unique identifier for the field")
    label: str = Field(..., description="Human-readable field label")
    type: VaultFieldType = Field(..., description="Field data type")


class VaultItem(BaseModel):
    """A credential item from a connected vault."""

    model_config = ConfigDict(populate_by_name=True)

    item_id: str = Field(..., alias="itemId", description="Credential URI or item identifier")
    connection_id: str | None = Field(None, alias="connectionId", description="ID of the owning connection")
    label: str = Field(..., description="Display label for the item")
    vault_name: str = Field(..., alias="vaultName", description="Name of the vault containing this item")
    domains: list[str] = Field(default_factory=list, description="Associated domain names")
    field_metadata: list[FieldMetadata] = Field(
        default_factory=list, alias="fieldMetadata", description="Metadata for available fields"
    )
    has_totp: bool = Field(False, alias="hasTotp", description="Whether this item has a TOTP code")


class VaultConnection(BaseModel):
    """A vault provider connection summary."""

    model_config = ConfigDict(populate_by_name=True)

    id: str = Field(..., description="Connection identifier")
    provider: VaultProvider = Field(..., description="Vault provider name")
    connection_status: str = Field(..., alias="connectionStatus", description="Current connection status")
    last_validated_at: str | None = Field(None, alias="lastValidatedAt", description="ISO timestamp of last validation")


class SyncSummary(BaseModel):
    """Summary of a vault items sync operation."""

    added: int = Field(..., description="Number of items added")
    updated: int = Field(..., description="Number of items updated")
    removed: int = Field(..., description="Number of items removed")


class VaultConnectResponse(BaseModel):
    """Response from connecting a vault provider."""

    model_config = ConfigDict(populate_by_name=True)

    connection_id: str = Field(..., alias="connectionId", description="Unique connection identifier")
    connected: bool = Field(..., description="Whether the connection was successful")
    provider: VaultProvider = Field(..., description="Vault provider name")
    items: list[VaultItem] = Field(default_factory=list, description="Items discovered during connection")


class VaultListConnectionsResponse(BaseModel):
    """Response listing all vault connections."""

    connections: list[VaultConnection] = Field(default_factory=list, description="List of vault connections")


class VaultDisconnectResponse(BaseModel):
    """Response from disconnecting a vault provider."""

    model_config = ConfigDict(populate_by_name=True)

    disconnected: bool = Field(..., description="Whether the disconnection was successful")
    connection_id: str = Field(..., alias="connectionId", description="ID of the disconnected connection")


class VaultListItemsResponse(BaseModel):
    """Response listing all vault items."""

    items: list[VaultItem] = Field(default_factory=list, description="List of vault items")


class VaultSyncItemsResponse(BaseModel):
    """Response from syncing vault items."""

    items: list[VaultItem] = Field(default_factory=list, description="Full list of items after sync")
    sync_summary: SyncSummary = Field(..., description="Summary of sync operation")
